// Only lines generated by this mixer's named sections are recognized as legacy mix text.
// Ordinary scene, lighting and negative-prompt sentences are never parsed away.
export function splitCreativePrompt(value){
  const prefixes=["Studio direction:","Camera motion direction:","Studio setup — schematic plan:","Camera motion plan — schematic:","Visual direction mix:","Visual direction mix (relative prompt emphasis):","Stíluskeverék:","Stilmischung:","Mélange de styles:","Mezcla de estilos:","Mix di stili:","Mistura de estilos:","Mieszanka stylów:","Lighting direction — descriptive strength:","Fényirányok — leíró erősség:","Licht — beschreibende Stärke:","Éclairage — intensité descriptive:","Iluminación — intensidad descriptiva:","Luci — intensità descrittiva:","Luz — intensidade descritiva:","Światło — siła opisowa:"];
  const scene=[],direction=[];for(const line of String(value||"").split("\n"))(prefixes.some(p=>line.trimStart().startsWith(p))?direction:scene).push(line);
  return {scene:scene.join("\n").trimEnd(),direction:direction.join("\n").trim()};
}
export function combineCreativePrompt(base,direction,{replaceLegacy=true}={}){
  if(!String(base||"").trim())return "";
  const scene=replaceLegacy?splitCreativePrompt(base).scene:String(base).trimEnd();
  return [scene,String(direction||"").trim()].filter(Boolean).join("\n");
}
export function creativePromptFor(scope,base,language="EN"){
  const detail={scope,base:String(base||""),language,prompt:String(base||"")};
  if(typeof document!=="undefined"&&typeof CustomEvent!=="undefined")document.dispatchEvent(new CustomEvent("prompt-studio-compose-mix",{detail}));
  return detail.prompt;
}
export function creativeMixSectionFor(scope,language="EN"){
  const detail={scope,base:"",language,prompt:"",direction:""};
  if(typeof document!=="undefined"&&typeof CustomEvent!=="undefined")document.dispatchEvent(new CustomEvent("prompt-studio-compose-mix",{detail}));
  return detail.direction;
}
export function loadCreativeMixSection(scope,direction){
  const detail={scope,direction:String(direction||""),accepted:false};
  if(typeof document!=="undefined"&&typeof CustomEvent!=="undefined")document.dispatchEvent(new CustomEvent("prompt-studio-load-mix-section",{detail}));
  return detail.accepted;
}
